lead_notes = [60, 64, 67, 71]
CHANNEL_COUNT = 3
PATTERN_ROWS = 64
for pat in range(3):
    print('Pattern', pat)
    for row in range(4):
        if pat == 0:
            note = lead_notes[row % 4]
            instr = 1
        elif pat == 1:
            if row % 8 == 0:
                note = 36
                instr = 2
            else:
                note = 255
                instr = 0
        else:
            if row % 8 == 0:
                note = 0
                instr = 3
            else:
                note = 255
                instr = 0
